use std::{fs,path::Path};
mod terrain_modes {pub use genewars_render::terrain_modes::*;}
#[path="entity_shadow.rs"]mod shadow;
fn main(){let arg=std::env::args().nth(1).unwrap();let p=Path::new(&arg);let input=fs::read(p.join("input.bin")).unwrap();let gla=fs::read(p.join("gla.bin")).unwrap();let table=terrain_modes::MainGlaTable::parse(&gla).unwrap();let mut cursor=0;let mut output=Vec::new();while cursor<input.len(){let b=&input[cursor..];let sw=b[0]as usize;let sh=b[1]as usize;let x=i16::from_le_bytes(b[2..4].try_into().unwrap());let y=i16::from_le_bytes(b[4..6].try_into().unwrap());let ox=i16::from_le_bytes(b[6..8].try_into().unwrap());let oy=i16::from_le_bytes(b[8..10].try_into().unwrap());let color=b[10];let flip=b[11];let n=sw*sh;let sprite=genewars_assets::IndexedSprite{width:sw as u8,height:sh as u8,indices:vec![0;n],opaque:b[12..12+n].iter().map(|&v|v!=0).collect(),consumed_bytes:0};let mut frame:Vec<u8>=(0..67*48).map(|i|(i*37+11)as u8).collect();if flip==0{shadow::draw_normal_component_shadow(&sprite,&table,[x,y],[ox,oy],color,[64,48],67,&mut frame).unwrap();}else{shadow::draw_hflipped_component_shadow(&sprite,&table,[x,y],[ox,oy],color,[64,48],67,&mut frame).unwrap();}output.extend(frame);cursor+=12+n;}fs::write(p.join("actual.bin"),output).unwrap();}
